INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N059-01','CN0026','S059-01','运行阶段关键纠正','§7.2.2 pp292–293；§3.2 p80','2025报告时一期400t/d已停用可检修备用，二期2000t/d在用，合计2400仅既有总能力；三期5200t/d拟替代现有，两站转备用。§3.2/表3.1使用m³/d，不能擅自换算。2026年底调试仅原报告计划。原设计排口尚未接通；未批准则沿用旧排口。','WEB_COMPANY','公开报告正文及图示文本；截图超时','2026-11-28'),
('N059-02','CN0026','S059-01','一期设施及膜边界','图2-9/10/11 pp36–40','一期2017验收，两条200m³/d线，1#图标Lymax L-EMT及Lymax MBR，MBR截留污泥、反洗管线，前沉降板框和后带式压滤不同；2#酸性微电解pH3–4、H2O2、NaOH、PAM、UASB、兼氧接触氧化、两次沉降与生物滤池，未列MBR。2025停用，不认作实际在用。','WEB_COMPANY','公开报告正文及图示文本；截图超时','2026-11-28'),
('N059-03','CN0026','S059-01','二期工艺及设备','图2-13及§2.1.4 pp41–43','四集水池分质、第5预留，FeCl3/PAM/NaOH除硅，电化学/芬顿旁路，双并联生化及MBR抽吸、NaClO杀菌、电吸附再生。正文电化学COD去除30–50%、SS≥90%、油≥95%是工艺描述非本厂实测。在线仪器Amtax Inter2C、CODmax II及pHG-2091，报告称大连墨土环境科技运维。','WEB_COMPANY','公开报告正文及图示文本；截图超时','2026-11-28'),
('N059-04','CN0026','S059-01','三期工艺与指标冲突','图7-3、表7.11/12 pp294–298','按完整设计流程未列MBR或其他污水膜，RO浓水为制水支流，电渗析酸水来源不明，不能把上游电渗析认作站内膜。重金属分项768t/d与单元558m³/d不同；一级A/O进水TN2616高于全站设计800并非同测点；高效沉淀TN42→42.5、去除率0保留。3207为生化路径单元水量，不是全站5200。','WEB_COMPANY','公开报告正文及图示文本；截图超时','2026-11-28'),
('N059-05','CN0026','S059-01','EHS组织及许可','§2.1.6 p43','报告时EHS部部长/总监1名、专员6名，负责职业卫生、安全、环境；日常环保人员监督设施维护。未列EHS姓名或直联，不将既有销售渠道冒充该部门。排污许可证91210200677529168F001V于2025-04-21重申领，有效至2030-04-20；非当前状态查询。','WEB_COMPANY','公开报告正文及图示文本；截图超时','2026-11-28'),
('N059-06','CN0026','S059-01','园区共享站','§7.2.2.5 p299','园区站总设计10万m³/d，一期2.5万、报告时接近饱和，拟深度处理扩建至5万；5万事故池非处理能力。改良A²/O、部分回用，其余入普兰店湾；非中触媒自建站。','WEB_COMPANY','公开报告正文及图示文本；截图超时','2026-11-28'),
('N059-07','CN0026','S059-01','膜优化与经济性','§7.2.2、图2-13、图7-3','三期设计转沉淀分离且旧站备用，潜在目标为澄清后深度回用，必须测盐分、季铵盐、硅、金属、温度、COD、实际负荷及浓水去向；不估实际成本。二期已有MBR，优先查膜龄/通量/TMP、清洗、电耗及检修窗口。','WEB_COMPANY','公开报告正文及图示文本；截图超时','2026-11-28');
